(26534,1,'2026-06-15 10:23:45','2026-06-15 08:23:45','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"industriesalon\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"site-main iss-front-page-main\",\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group site-main iss-front-page-main\"><!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-section\\u002d\\u002dhero iss-section\\u002d\\u002dfull-bleed\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group iss-section iss-section--hero iss-section--full-bleed\"><!-- wp:cover {\"url\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/industriesalon-1024x704.webp\",\"id\":25235,\"dimRatio\":40,\"customOverlayColor\":\"#a59b85\",\"isUserOverlayColor\":false,\"contentPosition\":\"bottom left\",\"isDark\":false,\"sizeSlug\":\"large\",\"className\":\"iss-front-hero\"} -->\n<div class=\"wp-block-cover is-light has-custom-content-position is-position-bottom-left iss-front-hero\"><img class=\"wp-block-cover__image-background wp-image-25235 size-large\" alt=\"\" src=\"http://192.168.2.31:8082/wp-content/uploads/2026/05/industriesalon-1024x704.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-40 has-background-dim\" style=\"background-color:#a59b85\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"className\":\"iss-front-hero__row\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-hero__row\"><!-- wp:group {\"className\":\"iss-front-hero__shell\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-hero__shell\"><!-- wp:group {\"className\":\"iss-heading iss-front-hero__content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-front-hero__content\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dlight iss-kicker\\u002d\\u002dlg\"} -->\n<p class=\"iss-kicker iss-kicker--light iss-kicker--lg\">forum für</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"iss-heading__title iss-front-hero__title\"} -->\n<h1 class=\"wp-block-heading iss-heading__title iss-front-hero__title\">Industriekultur und Transformation</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-banner-slot\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-banner-slot\"><!-- wp:industriesalon/notice-banner /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"className\":\"iss-container iss-front-hero__actions-wrap\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container iss-front-hero__actions-wrap\"><!-- wp:buttons {\"className\":\"iss-front-hero__actions\"} -->\n<div class=\"wp-block-buttons iss-front-hero__actions\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"/fuehrungen/\">Führung buchen</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/salon-vermietung/\">Raum anfragen</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:iss/spine-strip {\"title\":\"Schöneweide\",\"kicker\":\"Wo sind wir\",\"text\":\"Die Industrielandschaft Schöneweide ist für die Elektropolis Berlin, nicht weniger charakteristisch – und nicht weniger wichtig – als die Museumsinsel für Spree-Athen.\",\"placeIds\":\"17960\",\"rotationDeg\":-17,\"biasX\":-4,\"biasY\":-60,\"mapScale\":1.4,\"theme\":\"red\",\"lineMode\":\"route\",\"directionLabel\":\"zu FZE\",\"directionLabelStart\":\"Nalepa str\",\"textMode\":\"quote\",\"textAttribution\":\"Prof. Dr. Norbert Husen(einer der prominentesten Denkmalpfleger Deutschlands)\",\"showMapMarkers\":true,\"className\":\"iss-front-spine-strip\"} /-->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-3-card-row iss-front-explore section\",\"layout\":{\"type\":\"default\"},\"anchor\":\"vor-ort\"} -->\n<section id=\"vor-ort\" class=\"wp-block-group iss-section iss-3-card-row iss-front-explore section\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-heading iss-4-card-row__heading iss-front-explore__heading\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-4-card-row__heading iss-front-explore__heading\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\"><strong>Vor Ort</strong><br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Den Industriesalon entdecken</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Der Industriesalon lässt sich vor Ort als Rundgang, Ausstellung und öffentlicher Termin erleben. Die kulturellen Zugänge stehen hier vor der Serviceebene.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-3-card-row__grid iss-front-explore__grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-3-card-row__grid iss-front-explore__grid\"><!-- wp:group {\"className\":\"iss-4-card-row__card iss-front-explore__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card iss-front-explore__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":26050,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><img src=\"/wp-content/uploads/2026/06/2024-09-05-Sven-Bock-Touren-Industriesalon-Vermittlung-Industriekultur-45-1024x768.webp\" alt=\"\" class=\"wp-image-26050\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-explore__body\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-explore__body\"><!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\">Führungen</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-explore__text\"} -->\n<p class=\"iss-front-explore__text\">Entdecken Sie Industriegeschichte, Stadtraum und Transformation in unseren öffentlichen und buchbaren Rundgängen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/fuehrungen/\">Mehr erfahren</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__card iss-front-explore__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card iss-front-explore__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":26047,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><img src=\"/wp-content/uploads/2026/06/j.cizeikaite_industriesalon_03_400dpi-1024x683.webp\" alt=\"\" class=\"wp-image-26047\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-explore__body\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-explore__body\"><!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\">Ausstellungen</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-explore__text\"} -->\n<p class=\"iss-front-explore__text\">Objekte, Bilder und Dokumente zeigen Industriegeschichte im Zusammenhang von Ort und Produktion.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/ausstellungen/\">Mehr erfahren</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__card iss-front-explore__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card iss-front-explore__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":26048,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><img src=\"/wp-content/uploads/2026/06/Im-Industriesalon_Vortrag-1024x683.webp\" alt=\"\" class=\"wp-image-26048\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-explore__body\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-explore__body\"><!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\">Veranstaltungen</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-explore__text\"} -->\n<p class=\"iss-front-explore__text\">Vorträge, Gespräche und kleinere Formate bringen Gegenwart und Industriekultur zusammen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/veranstaltungen/\">Mehr erfahren</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-front-projects section section\\u002d\\u002dplain\",\"layout\":{\"type\":\"default\"},\"anchor\":\"projekte\"} -->\n<section id=\"projekte\" class=\"wp-block-group iss-section iss-front-projects section section--plain\"><!-- wp:group {\"className\":\"iss-front-projects__inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-projects__inner\"><!-- wp:group {\"className\":\"iss-front-projects__intro iss-heading iss-heading\\u002d\\u002duncaged\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-projects__intro iss-heading iss-heading--uncaged\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Projekte</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title iss-front-projects__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title iss-front-projects__title\">Aktuelle Projekte</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Projekte machen sichtbar, woran der Industriesalon derzeit arbeitet. Sie bündeln Forschung, Sammlungsarbeit, Kooperationen und Entwicklungsprozesse rund um Schöneweide und seine Industriegeschichte. Hier entstehen neue Inhalte, Netzwerke und Perspektiven, die langfristig in Ausstellungen, Publikationen, Vermittlungsangebote und den öffentlichen Diskurs einfließen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-projects__link\"} -->\n<p class=\"iss-front-projects__link\"><a class=\"iss-action-link\" href=\"/projekte/\">Alle Projekte ansehen</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:query {\"queryId\":24,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"projekt\",\"order\":\"asc\",\"orderBy\":\"menu_order\",\"inherit\":false},\"className\":\"iss-front-projects__query\"} -->\n<div class=\"wp-block-query iss-front-projects__query\"><!-- wp:post-template {\"className\":\"iss-front-projects__items\"} -->\n<!-- wp:group {\"tagName\":\"article\",\"className\":\"iss-front-project-card\",\"layout\":{\"type\":\"default\"}} -->\n<article class=\"wp-block-group iss-front-project-card\"><!-- wp:group {\"className\":\"iss-front-project-card__meta\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-project-card__meta\"><!-- wp:iss/project-status {\"className\":\"iss-front-project-card__terms iss-front-project-card__termsu002du002dstatus\"} /-->\n\n<!-- wp:post-terms {\"term\":\"iss_topic\",\"separator\":\" · \",\"className\":\"iss-front-project-card__terms iss-front-project-card__termsu002du002dtopics\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:post-featured-image {\"isLink\":true,\"scale\":\"contain\",\"className\":\"iss-front-project-card__media\"} /-->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"className\":\"iss-front-project-card__title\"} /-->\n\n<!-- wp:post-excerpt {\"moreText\":\"Projekt öffnen\",\"excerptLength\":24,\"className\":\"iss-front-project-card__excerpt\"} /--></article>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-no-results -->\n<!-- wp:group {\"className\":\"iss-front-projects__empty\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-projects__empty\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Keine Einträge</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Es sind noch keine Projekte veröffentlicht.</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n<!-- /wp:query-no-results --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-section\\u002d\\u002dtimeline section section\\u002d\\u002dcompact\",\"layout\":{\"type\":\"default\"},\"anchor\":\"gegenwart\"} -->\n<section id=\"gegenwart\" class=\"wp-block-group iss-section iss-section--timeline section section--compact\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-timeline-section__header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-timeline-section__header\"><!-- wp:industriesalon/notice-banner {\"area\":\"front_page_timeline_promo\",\"skin\":\"pinned\",\"className\":\"iss-timeline-promo-slot\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"className\":\"iss-timeline-section__intro-col\"} -->\n<div class=\"wp-block-column iss-timeline-section__intro-col\"><!-- wp:group {\"metadata\":{\"name\":\"timeline\"},\"className\":\"iss-heading iss-timeline-section__intro\"} -->\n<div class=\"wp-block-group iss-heading iss-timeline-section__intro\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\">Gegenwart</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-timeline__title\"} -->\n<h2 class=\"wp-block-heading iss-timeline__title\">Demnächst im Industriesalon</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Termine, Gespräche, Repair Café und Rundgänge zeigen den Industriesalon als aktiven Ort im Wandel. Das Programm bleibt in Bewegung und wird laufend ergänzt.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"iss-front-gegenwart__actions\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-gegenwart__actions\"><!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/veranstaltungen/\">Veranstaltungen ansehen</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/repair-cafe/\">Repair Café</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a class=\"iss-action-link\" href=\"/kalender/\">Zum Kalender</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"iss-timeline-section__list-col\"} -->\n<div class=\"wp-block-column iss-timeline-section__list-col\"><!-- wp:industriesalon/timeline-query {\"shellMode\":\"body\",\"limit\":4,\"showMeta\":false,\"includeRunningRanges\":true,\"fixedItemTypesList\":[\"fuehrungen\",\"veranstaltungen\"],\"showItemTypeFilter\":false,\"groupRecurringTours\":true,\"groupRecurringToursByMonth\":true,\"showRecurringNote\":false,\"showBottomButton\":true,\"bottomButtonText\":\"Alle Termine ansehen\",\"bottomButtonUrl\":\"/kalender/\",\"ticketsButtonText\":\"Buchen\",\"className\":\"iss-timelineu002du002dscheme-scarlet-red\"} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-section\\u002d\\u002drental section section\\u002d\\u002dplain\",\"layout\":{\"type\":\"default\"},\"anchor\":\"raum-nutzen\"} -->\n<section id=\"raum-nutzen\" class=\"wp-block-group iss-section iss-section--rental section section--plain\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"stretch\",\"className\":\"iss-front-rental__grid\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-stretch iss-front-rental__grid\"><!-- wp:column {\"verticalAlignment\":\"stretch\",\"width\":\"50%\",\"className\":\"iss-front-rental__info-col\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch iss-front-rental__info-col\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"iss-info-panel iss-front-rental__panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-info-panel iss-front-rental__panel\"><!-- wp:group {\"className\":\"iss-heading iss-front-rental__heading\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-front-rental__heading\"><!-- wp:paragraph {\"className\":\"iss-kicker iss-kicker\\u002d\\u002dcompact\"} -->\n<p class=\"iss-kicker iss-kicker--compact\">Raum nutzen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title iss-front-rental__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title iss-front-rental__title\">Salon mieten</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text iss-front-rental__claim\"} -->\n<p class=\"iss-heading__text iss-front-rental__claim\">Veranstaltungen, Workshops und Empfänge in einer ehemaligen Produktionshalle, mitten im historischen Industriegebiet von Schöneweide.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-rental__facts\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-rental__facts\"><!-- wp:group {\"className\":\"iss-front-rental__fact\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-rental__fact\"><!-- wp:paragraph {\"className\":\"iss-front-rental__fact-value\"} -->\n<p class=\"iss-front-rental__fact-value\"><strong>650 m²</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-rental__fact-label\"} -->\n<p class=\"iss-front-rental__fact-label\">Halle mit Ausstellung und Galerie</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-rental__fact\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-rental__fact\"><!-- wp:paragraph {\"className\":\"iss-front-rental__fact-value\"} -->\n<p class=\"iss-front-rental__fact-value\"><strong>350 m²</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-rental__fact-label\"} -->\n<p class=\"iss-front-rental__fact-label\">Ausstellungsraum, 7 m Höhe</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-front-rental__fact\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-rental__fact\"><!-- wp:paragraph {\"className\":\"iss-front-rental__fact-value\"} -->\n<p class=\"iss-front-rental__fact-value\"><strong>100 m²</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-rental__fact-label\"} -->\n<p class=\"iss-front-rental__fact-label\">Veranstaltungsraum mit Bühne und Terrasse</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"iss-front-rental__note\"} -->\n<p class=\"iss-front-rental__note\">Stühle, Tische, WLAN, Tonanlage, Beamer und Leinwand können nach Bedarf genutzt werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"className\":\"iss-front-rental__actions\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons iss-front-rental__actions\"><!-- wp:button {\"className\":\"iss-front-rental__button\"} -->\n<div class=\"wp-block-button iss-front-rental__button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/salon-vermietung/\">Details und Anfrage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\",\"width\":\"50%\",\"className\":\"iss-front-rental__media-col\"} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch iss-front-rental__media-col\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"iss-front-rental__media\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-front-rental__media\"><!-- wp:image {\"id\":13313,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"iss-front-rental__image\"} -->\n<figure class=\"wp-block-image size-large iss-front-rental__image\"><img src=\"/wp-content/uploads/2026/05/rental1-1024x695.png\" alt=\"Salonvermietung im Industriesalon\" class=\"wp-image-13313\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"metadata\":{\"categories\":[\"industriesalon\"],\"patternName\":\"industriesalon/4-card-row\",\"name\":\"ISS 4 Card Row\"},\"className\":\"iss-section iss-4-card-row section\\u002d\\u002dcompact\",\"layout\":{\"type\":\"default\"},\"anchor\":\"archiv-wissen\"} -->\n<section id=\"archiv-wissen\" class=\"wp-block-group iss-section iss-4-card-row section--compact\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-heading iss-4-card-row__heading\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-4-card-row__heading\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\">Archiv &amp; Wissen</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Quellen, Erinnerung und Entwicklung</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text\"} -->\n<p class=\"iss-heading__text\">Archiv, Sammlungen, Publikationen und Videos machen die historischen Schichten Schöneweides sichtbar. Sie dokumentieren industrielle Entwicklungen, gesellschaftliche Veränderungen und die Menschen, die den Standort geprägt haben.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__grid\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__grid\"><!-- wp:group {\"className\":\"iss-4-card-row__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":13327,\"sizeSlug\":\"full\",\"linkDestination\":\"custom\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-full iss-4-card-row__image\"><a href=\"/sammlungen/\"><img src=\"/wp-content/uploads/2026/05/archiv1.png\" alt=\"\" class=\"wp-image-13327\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\"><a href=\"/sammlungen/\">Sammlungen</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-4-card-row__action\"} -->\n<p class=\"iss-4-card-row__action\"><a class=\"iss-card__link\" href=\"/sammlungen/\">Weiter</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":12426,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><a href=\"/publikationen/\"><img src=\"/wp-content/uploads/2026/04/715yWXXfaFL._SL1500_-1024x977.jpg\" alt=\"Publikation\" class=\"wp-image-12426\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\"><a href=\"/publikationen/\">Publikationen</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-4-card-row__action\"} -->\n<p class=\"iss-4-card-row__action\"><a class=\"iss-card__link\" href=\"/publikationen/\">Weiter</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":5348,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><img src=\"/wp-content/uploads/2022/05/emil_rathenau-e1780575430497-923x1024.jpg\" alt=\"\" class=\"wp-image-5348\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\"><a href=\"/archiv/\">Archiv</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-4-card-row__action\"} -->\n<p class=\"iss-4-card-row__action\"><a class=\"iss-card__link\" href=\"/archiv/\">Weiter</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-4-card-row__card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__card\"><!-- wp:group {\"className\":\"iss-4-card-row__media iss-media-card iss-media-card\\u002d\\u002dgrey iss-media-card\\u002d\\u002dcover iss-media-card\\u002d\\u002dsoft iss-media-card\\u002d\\u002drail-thin\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-4-card-row__media iss-media-card iss-media-card--grey iss-media-card--cover iss-media-card--soft iss-media-card--rail-thin\"><!-- wp:image {\"id\":26041,\"sizeSlug\":\"large\",\"linkDestination\":\"custom\",\"className\":\"iss-4-card-row__image\"} -->\n<figure class=\"wp-block-image size-large iss-4-card-row__image\"><img src=\"/wp-content/uploads/2026/06/video-1024x576.webp\" alt=\"\" class=\"wp-image-26041\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3,\"className\":\"iss-card__title iss-4-card-row__title\"} -->\n<h3 class=\"wp-block-heading iss-card__title iss-4-card-row__title\"><a href=\"/videos/\">Videos</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-4-card-row__action\"} -->\n<p class=\"iss-4-card-row__action\"><a class=\"iss-card__link\" href=\"/videos/\">Weiter</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"metadata\":{\"categories\":[\"industriesalon\"],\"patternName\":\"industriesalon/50-50-media-text\",\"name\":\"ISS 50/50 Media Text\"},\"className\":\"iss-section iss-media-text iss-media-text\\u002d\\u002d45-55 iss-media-text\\u002d\\u002dgap-l section iss-media-text\\u002d\\u002dflip iss-media-text\\u002d\\u002doverlay-heading section\\u002d\\u002dalt\",\"layout\":{\"type\":\"default\"},\"anchor\":\"industriesalon\"} -->\n<section id=\"industriesalon\" class=\"wp-block-group iss-section iss-media-text iss-media-text--45-55 iss-media-text--gap-l section iss-media-text--flip iss-media-text--overlay-heading section--alt\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"className\":\"iss-media-text__layout\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top iss-media-text__layout\"><!-- wp:column {\"verticalAlignment\":\"top\",\"className\":\"iss-media-text__content\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top iss-media-text__content\"><!-- wp:group {\"className\":\"iss-media-text__inner\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-text__inner\"><!-- wp:group {\"className\":\"iss-microblocks\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblocks\"><!-- wp:group {\"className\":\"iss-microblock\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock\"><!-- wp:html -->\n<p class=\"iss-microblock__icon\" aria-hidden=\"true\"><span class=\"iss-icon iss-icon--location iss-icon--accent\" aria-hidden=\"true\"></span></p>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"iss-microblock__content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock__content\"><!-- wp:heading {\"level\":4,\"className\":\"iss-microblock__title\"} -->\n<h4 class=\"wp-block-heading iss-microblock__title\">Arbeitsweise</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-microblock__text\"} -->\n<p class=\"iss-microblock__text\">Mitglieder werden über Aktivitäten und Entwicklungen auf dem Laufenden gehalten. Gleichzeitig bleibt Raum für Begegnung, Feiern, Gespräche und die gemeinsame Arbeit an einem besonderen Ort.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-microblock\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock\"><!-- wp:html -->\n<p class=\"iss-microblock__icon\" aria-hidden=\"true\"><span class=\"iss-icon iss-icon--award iss-icon--accent\" aria-hidden=\"true\"></span></p>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"iss-microblock__content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock__content\"><!-- wp:heading {\"level\":4,\"className\":\"iss-microblock__title\"} -->\n<h4 class=\"wp-block-heading iss-microblock__title\">Mitarbeit</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-microblock__text\"} -->\n<p class=\"iss-microblock__text\">Der Industriesalon lebt nicht nur von Beständen, sondern von Menschen, die führen, ordnen, recherchieren, aufbauen, zuhören oder einfach mit anpacken.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-microblock\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock\"><!-- wp:html -->\n<p class=\"iss-microblock__icon\" aria-hidden=\"true\"><span class=\"iss-icon iss-icon--group iss-icon--accent\" aria-hidden=\"true\"></span></p>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"iss-microblock__content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock__content\"><!-- wp:heading {\"level\":4,\"className\":\"iss-microblock__title\"} -->\n<h4 class=\"wp-block-heading iss-microblock__title\">Mitglied werden</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-microblock__text\"} -->\n<p class=\"iss-microblock__text\">Wer den Industriesalon unterstützen möchte, kann Mitglied werden, mitarbeiten oder spenden. Die Formen sind verschieden, aber sie sichern denselben Ort.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-microblock\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock\"><!-- wp:html -->\n<p class=\"iss-microblock__icon\" aria-hidden=\"true\"><span class=\"iss-icon iss-icon--roof iss-icon--accent\" aria-hidden=\"true\"></span></p>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"iss-microblock__content\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-microblock__content\"><!-- wp:heading {\"level\":4,\"className\":\"iss-microblock__title\"} -->\n<h4 class=\"wp-block-heading iss-microblock__title\">Netzwerk im Stadtteil</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-microblock__text\"} -->\n<p class=\"iss-microblock__text\">Der Industriesalon arbeitet mit Nachbarschaft, Initiativen, Schulen, Kulturpartnern und lokalen Akteuren zusammen. Dadurch entsteht ein Ort, der nicht nur bewahrt, sondern Austausch ermöglicht und Schöneweide als gemeinsamen Erinnerungs- und Erfahrungsraum stärkt.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"iss-media-text__actions\"} -->\n<p class=\"iss-media-text__actions\"><a class=\"iss-media-text__link\" href=\"/about/\">Weiter</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"className\":\"iss-media-text__media-col\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top iss-media-text__media-col\"><!-- wp:group {\"className\":\"iss-media-text__media iss-media-card iss-media-card\\u002d\\u002dred iss-media-card\\u002d\\u002dcover\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-media-text__media iss-media-card iss-media-card--red iss-media-card--cover\"><!-- wp:group {\"className\":\"iss-heading iss-media-text__heading\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-media-text__heading\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\">Industriesalon</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title iss-media-text__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title iss-media-text__title\">Über uns</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text iss-media-text__text\"} -->\n<p class=\"iss-heading__text iss-media-text__text\">Der Industriesalon Schöneweide ist Museum, Lernort und Ausgangspunkt, um den Stadtteil über seine Industriegeschichte, seine Architektur und seine heutigen Veränderungen zu verstehen.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":180,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-media-text__image\"} -->\n<figure class=\"wp-block-image size-full iss-media-text__image\"><img src=\"/wp-content/uploads/2019/02/2030-20171001-boxenstopp-3483.jpg\" alt=\"\" class=\"wp-image-180\"/><figcaption class=\"wp-element-caption\">Industriesalon Schöneweide<br>Ausstellungsort präsentieren</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-section\\u002d\\u002dvisit-info\",\"layout\":{\"type\":\"default\"},\"anchor\":\"besuch\"} -->\n<section id=\"besuch\" class=\"wp-block-group iss-section iss-section--visit-info\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:group {\"className\":\"iss-visit-info iss-visit-info\\u002d\\u002dinfo-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-visit-info iss-visit-info--info-panel\"><!-- wp:industriesalon/visit-info {\"shellMode\":\"body\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-section iss-section\\u002d\\u002dnewsletter section\",\"layout\":{\"type\":\"default\"}} -->\n<section class=\"wp-block-group iss-section iss-section--newsletter section\"><!-- wp:group {\"className\":\"iss-container\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-container\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"iss-newsletter-band__grid\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center iss-newsletter-band__grid\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"60%\",\"className\":\"iss-newsletter-band__main\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center iss-newsletter-band__main\" style=\"flex-basis:60%\"><!-- wp:group {\"className\":\"iss-heading iss-heading\\u002d\\u002duncaged iss-newsletter-band__heading\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-heading iss-heading--uncaged iss-newsletter-band__heading\"><!-- wp:paragraph {\"className\":\"iss-kicker\"} -->\n<p class=\"iss-kicker\">Auf dem Laufenden bleiben</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"iss-heading__title\"} -->\n<h2 class=\"wp-block-heading iss-heading__title\">Zum Newsletter anmelden</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"iss-heading__text iss-newsletter-band__lead\"} -->\n<p class=\"iss-heading__text iss-newsletter-band__lead\">Erhalten Sie Hinweise zu Veranstaltungen, Ausstellungen, Führungen und Neuigkeiten aus dem Industriesalon Schöneweide direkt per E-Mail.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"iss-newsletter-band__formwrap\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group iss-newsletter-band__formwrap\"><!-- wp:iss/newsletter-form /--></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"iss-newsletter-band__note\",\"fontSize\":\"small\"} -->\n<p class=\"iss-newsletter-band__note has-small-font-size\">Ich möchte aktuelle Infos aus dem Industriesalon erhalten und mich für den Newsletter anmelden. Eine Abmeldung ist jederzeit möglich. Mit der Eingabe meiner E-Mail-Adresse erkläre ich mich mit der <a href=\"/verein/#datenschutz\">Datenschutzerklärung</a> einverstanden.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\",\"className\":\"iss-newsletter-band__side\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center iss-newsletter-band__side\" style=\"flex-basis:40%\"><!-- wp:group {\"className\":\"iss-newsletter-band__support\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-newsletter-band__support\"><!-- wp:paragraph {\"className\":\"iss-newsletter-band__support-title\"} -->\n<p class=\"iss-newsletter-band__support-title\">Wir bedanken uns herzlich für die Unterstützung durch den</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":25727,\"width\":\"520px\",\"height\":\"auto\",\"aspectRatio\":\"5.511961722488039\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-newsletter-band__logo\"} -->\n<figure class=\"wp-block-image size-full is-resized iss-newsletter-band__logo\"><img src=\"/wp-content/uploads/2026/05/walk-of-fame-schoeneweide-foerderlogos.jpeg\" alt=\"Logos von Bezirksamt Treptow-Köpenick, Senatsverwaltung und Berlin\" class=\"wp-image-25727\" style=\"aspect-ratio:5.511961722488039;width:520px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"className\":\"iss-newsletter-band__partners\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-newsletter-band__partners\"><!-- wp:paragraph {\"className\":\"iss-newsletter-band__partners-title\"} -->\n<p class=\"iss-newsletter-band__partners-title\">Unsere Tourismuspartner:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"iss-newsletter-band__partner-logos\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-newsletter-band__partner-logos\"><!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo\\u002d\\u002dvisit-berlin\"} -->\n<figure class=\"wp-block-image size-full iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo--visit-berlin\"><img src=\"/wp-content/uploads/2019/04/Visti-Berlin-350x150-e1575551506288.png\" alt=\"visitBerlin\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo\\u002d\\u002derih\"} -->\n<figure class=\"wp-block-image size-full iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo--erih\"><img src=\"/wp-content/uploads/2019/04/ERIH-Logo-350x150-e1575551585914.png\" alt=\"ERIH - European Route of Industrial Heritage\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo\\u002d\\u002dbzi\"} -->\n<figure class=\"wp-block-image size-full iss-newsletter-band__partner-logo iss-newsletter-band__partner-logo--bzi\"><img src=\"/wp-content/uploads/2019/12/BZI-e1575551630496.png\" alt=\"Berliner Zentrum Industriekultur\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></section>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"industriesalon\"} /-->','Front Page','Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.','publish','closed','closed','','front-page','','','2026-06-29 10:52:09','2026-06-29 08:52:09','',0,'http://192.168.2.31:8082/front-page/',0,'wp_template','',0);
